using System.Numerics;
using Raylib_cs;
namespace UnnamedGame;

/// F1: a testing menu for weather, sky events, time, travel and fishing. The game keeps running behind it.
public sealed partial class GameScreen
{
    bool admin, hideHud; int admTab; float frenzyT, quakeT, quakeLen, quakeDust; const float AW = 190; public bool OverAdmin => admin && panel == Panel.None && Ui.Mouse.X < AW + 14 && Ui.Mouse.Y > 44;
    public void ToggleAdminForTest() => admin = !admin;
    void AdminTick(float dt) { frenzyT = MathF.Max(0, frenzyT - dt); Fish.Frenzy = frenzyT > 0; if (quakeT > 0) { quakeT -= dt; float k = M.Smooth(0, 1.2f, quakeLen - quakeT) * M.Smooth(0, 1.8f, quakeT); Shake(.4f + 3.4f * k * (.6f + .4f * M.Noise(time * 3))); quakeDust -= dt; if (quakeDust < 0 && k > .25f) { quakeDust = .08f; float qx = CamX + rng.F() * Ui.VW; Life.Dust(new(qx, W.Top[Math.Clamp((int)(qx / 24), 0, World.W - 1)] * 24), "dirt", 3, 0); if (rng.P(.3f)) Life.Leaves(new(qx, CamY + 60), 2, World.GrassCol(qx / 24)); } } }
    void Admin()
    {
        float x = 8, y = 46, w = AW, h = Ui.VH - 56; Ui.Nine("panel", x, y, w, h, Color.White); Font.Draw("Admin", x + 13, y + 11, Ui.Ink, 1.5f); Font.Draw("F1 to close", x + w - 13, y + 14, Ui.Soft, .85f, 1); string[] tb = ["Weather", "Sky", "Time", "Travel", "Fish"]; float tw = (w - 24 - 8) / 5; for (int i = 0; i < 5; i++) if (Ui.Button("ad" + i, tb[i], x + 12 + i * (tw + 2), y + 27, tw, 16, "btnP", on: admTab == i, text: .8f)) admTab = i;
        float cx = x + 13, cy = y + 50, cw = w - 26; int n = 0; bool B(string label, string style = "btn", string tip = null) { float bw = (cw - 4) / 2; bool r = Ui.Button("adb" + admTab + "_" + n, label, cx + (n % 2) * (bw + 4), cy + (n / 2) * 22, bw, 19, style, null, tip); n++; return r; } void Gap(string title) { if (n % 2 == 1) n++; cy += (n / 2) * 22 + 4; n = 0; Font.Draw(title, cx, cy, Ui.Soft); cy += 11; }
        switch (admTab)
        {
            case 0:
                foreach (var q in Enum.GetValues<Weather>()) if (B(q.ToString(), Env.Now == q ? "btnG" : "btnB")) { Env.SetWeather(q); Env.WeatherT = 600; Toast(q + " is building. Use Instant to skip ahead"); }
                if (B("Instant", "btnP", "Skip the slow change")) { var now = Env.Now; Env.SetWeather(now, true); }
                Gap("Wind"); { float v = Env.WindForce < 0 ? Env.Wind / 1.6f : Env.WindForce / 1.6f; if (Ui.Slider("adw", ref v, cx + 2, cy, cw - 6)) Env.WindForce = v * 1.6f; cy += 16; } if (B("Natural wind", "btnP")) Env.WindForce = -1; if (B("Gentle gust")) { P.An.Gust(1.4f); Life.Leaves(P.P + new Vector2(-60, -50), 16, World.GrassCol(P.P.X / 24)); Snd.Play("whoosh", .6f, .7f); }
                Gap("Events"); if (B("Lightning")) { Env.Flash = 1.1f; Env.BoltT = 0; Env.BoltX = .15f + rng.F() * .7f; Env.BoltSeed = rng.I(9999); Snd.Play("thunder", .9f); Shake(2); } if (B("Rainbow")) Env.RainbowGoal = 70; if (B("Petal shower")) Life.Petals(0, 26); if (B("Leaf storm")) Life.Petals(1, 26); if (B("Earthquake", "btnR")) { quakeT = quakeLen = 6; Snd.Play("thunder", .8f, .5f); Life.Scatter(CamX, CamY, (int)Ui.VW); } if (B("Melt snow", "btnP")) { Env.Melting = true; if (Env.Now == Weather.Snow) Env.SetWeather(Weather.Clear); } break;
            case 1:
                if (B("Shooting star")) { Env.SpawnMeteor(false, rng.P(.35f)); if (Env.Night < .5f) Toast("Only visible at night"); } if (B("Meteor shower")) { Env.MeteorT = 45; if (Env.Night < .5f) Env.FastForward(.93f); } if (B(Env.ForceAurora ? "Aurora off" : "Aurora", Env.ForceAurora ? "btnG" : "btn")) { Env.ForceAurora = !Env.ForceAurora; if (Env.ForceAurora && Env.Night < .5f) Env.FastForward(.93f); } if (B("Solar eclipse")) { if (Env.Night > .4f) Env.FastForward(.45f); Env.EclipseT = Env.EclipseLen; Snd.Play("area", .6f, .7f); } if (B("Clear sky")) Env.SetWeather(Weather.Clear, true); if (B("Full clouds")) Env.SetWeather(Weather.Cloudy, true);
                Gap("Wildlife"); if (B("Bird flock")) Life.Flock(CamX, CamY, (int)Ui.VW); if (B("Scare birds")) Life.Scatter(CamX, CamY, (int)Ui.VW); if (B("Firefly swarm")) Life.Swarm(P.P + new Vector2(0, -40)); if (B("Sparkles")) Life.Sparkle(P.P + new Vector2(0, -50), 40, new Color(255, 226, 140, 255)); break;
            case 2:
                (string l, float c)[] tm = [("Sunrise", .262f), ("Morning", .33f), ("Noon", .5f), ("Afternoon", .62f), ("Golden hour", .70f), ("Sunset", .757f), ("Dusk", .80f), ("Night", .90f), ("Midnight", .999f), ("Before dawn", .22f)]; foreach (var q in tm) if (B(q.l, "btnB")) Env.FastForward(q.c);
                Gap("Time of day"); { float v = Env.Clock; if (Ui.Slider("adt", ref v, cx + 2, cy, cw - 6)) { Env.Clock = M.Clamp(v, 0, .9995f); Env.Colors(); } cy += 16; } Font.Draw(Env.TimeText + "   Day " + Env.Day, cx, cy, Ui.Ink); cy += 12; if (B(Env.TimeScale == 0 ? "Unfreeze" : "Freeze time", Env.TimeScale == 0 ? "btnG" : "btn")) Env.TimeScale = Env.TimeScale == 0 ? 1 : 0; if (B("Fast x30", Env.TimeScale > 5 ? "btnG" : "btn")) Env.TimeScale = Env.TimeScale > 5 ? 1 : 30; if (B("Next day")) Env.Day++; break;
            case 3:
                (string l, float tx, float ty)[] pl = [("Village", 762, 0), ("Beach W", 138, 0), ("Birchwood", 224, 0), ("River", 293, 0), ("Amber Forest", 386, 0), ("Waterfall top", 462, 0), ("Behind falls", 446, 90), ("Lake dock", 588, 94), ("Meadow", 654, 0), ("Hills", 985, 0), ("Highlands", 1215, 0), ("Cave", 1176, 103), ("Cave pool", 1184, 104), ("Beach E", 1410, 0)]; foreach (var q in pl) if (B(q.l, "btnB")) { P.P = new(q.tx * 24 + 12, q.ty > 0 ? W.FloorAt((int)q.tx, (int)q.ty) : W.Top[(int)q.tx] * 24); P.V = default; P.StandUp(); Fish.Cancel(); CamX = P.P.X - Ui.VW / 2; CamY = P.P.Y - 34 - Ui.VH * .66f; Life.Sparkle(P.P + new Vector2(0, -40), 14, new Color(255, 236, 170, 255)); Snd.Play("whoosh", .6f); }
                if (B(hideHud ? "Show HUD" : "Hide HUD", hideHud ? "btnG" : "btnP")) hideHud = !hideHud; if (B("Reveal map", "btnP")) foreach (var a in new[] { "The West Sea", "Driftwood Beach", "Birchwood", "Maple River", "Amber Forest", "Lake Lantern", "Clover Meadow", "Lantern Village", "Rolling Hills", "Pinecrest Highlands", "Sunrise Shore", "The East Sea", "Glowcap Caverns", "Behind the Falls" }) Store.Data.Areas.Add(a); break;
            default:
                var d = Store.Data; if (B("+500 coins", "btnG")) { d.Coins += 500; Snd.Play("coins"); } if (B("10 of each bait", "btnG")) { for (int i = 1; i < 12; i++) d.Baits[i] = Math.Min(99, d.Baits[i] + 10); if (d.Bait == 0) d.Bait = 1; Toast("Bait stocked"); } if (B("All rods", "btnG")) { for (int i = 0; i < 5; i++) d.Rods[i] = true; Toast("All rods unlocked"); } if (B("All lures", "btnG")) { for (int i = 0; i < 6; i++) d.Lures[i] = true; Toast("All lures unlocked"); } if (B("Bite now", "btnB", "While the line is in the water")) Fish.ForceBite(-1); if (B("Fish frenzy", frenzyT > 0 ? "btnG" : "btnB", "Instant bites for a minute")) { frenzyT = 60; Toast("Fish frenzy!"); } if (B("Big next fish", "btnB")) { Fish.NextFish = 6; Toast("Next cast: a big one"); } if (B("Legend next", "btnR")) { var lg = Enumerable.Range(0, FishDex.All.Length).Where(i => FishDex.All[i].Legend).ToList(); Fish.NextFish = lg[rng.I(lg.Count)]; Toast("Next cast: " + FishDex.All[Fish.NextFish].Name); } if (B("Regrow forage", "btnB")) { d.ForageTimes.Clear(); Toast("Everything regrew"); } if (B("Random fish x5", "btnB")) { for (int i = 0; i < 5 && d.Fish.Count < 60; i++) { int id = rng.I(FishDex.All.Length); var (kg, cm) = FishDex.Roll(FishDex.All[id], rng, .2f); d.Fish.Add(new FishItem { Id = id, Kg = kg, Cm = cm }); } Toast("Fish added"); } break;
        }
    }
}
